  // sync with the rtl
  bit   synchronised_sleep_mode_i;
  do begin
    synchronised_sleep_mode_i = cfg.hdl_read_bit(.path(".aon_sleep_mode"));
    if ( (wdog_pause_in_sleep & synchronised_sleep_mode_i))
      cfg.aon_clk_rst_vif.wait_clks(1);
